<template>
  <section class="discount-admin page-section"><div class="container discount-admin__inner">
    <header class="discount-admin__head"><span>Ценообразование</span><h1 class="page-title">Скидки от суммы заказа</h1><p>Правило применяется к стоимости товаров после индивидуальных акций, но до доставки. Например: от 10 000 ₽ — 5%, от 20 000 ₽ — 10%. Так покупателю не нужно считать мешки разных товаров.</p></header>
    <div class="discount-admin__layout">
      <form class="card discount-create" @submit.prevent="createRule"><div><span class="discount-card__eyebrow">Новое правило</span><h2>Добавить уровень</h2></div>
        <label class="field"><span class="field__label">Сумма корзины от, ₽</span><AppNumberInput v-model="form.min_subtotal" :min="1" :step="1" suffix="₽" required aria-label="Сумма корзины от" /><small>Считается по товарам после товарных акций. Доставка в порог не входит.</small></label>
        <label class="field"><span class="field__label">Скидка на корзину, %</span><AppNumberInput v-model="form.percent" :min="1" :max="30" :step="1" suffix="%" required aria-label="Скидка на корзину" /><small>Максимум 30%. Если подходит несколько уровней, применяется самый высокий.</small></label>
        <div class="discount-preview">При сумме от <strong>{{ money(form.min_subtotal) }}</strong> покупатель получит <strong>−{{ Number(form.percent||0) }}%</strong>.</div><button class="btn btn--primary" type="submit">Добавить правило</button>
      </form>
      <section class="card discount-rules"><div class="discount-rules__head"><div><span class="discount-card__eyebrow">Действующие настройки</span><h2>Уровни скидок</h2></div><strong>{{ rules.length }}</strong></div><p v-if="!rules.length" class="discount-empty">Правил пока нет.</p>
        <article v-for="r in rules" :key="r.id" class="discount-rule"><div class="discount-rule__summary"><strong>От {{ money(r.min_subtotal) }} → −{{ Number(r.percent) }}%</strong><span :class="{'is-off':!r.is_active}">{{ r.is_active?'Активно':'Выключено' }}</span></div><div class="discount-rule__fields"><label class="field"><span class="field__label">Сумма от, ₽</span><AppNumberInput v-model="r.min_subtotal" :min="1" :step="1" suffix="₽" aria-label="Сумма от" /></label><label class="field"><span class="field__label">Скидка, %</span><AppNumberInput v-model="r.percent" :min="1" :max="30" :step="1" suffix="%" aria-label="Скидка" /></label></div><label class="discount-toggle"><input v-model="r.is_active" type="checkbox"><span></span><b>Правило активно</b></label><div class="discount-rule__actions"><button class="btn btn--secondary" type="button" @click="save(r)">Сохранить</button><button class="btn btn--ghost" type="button" @click="remove(r)">Удалить</button></div></article>
      </section>
    </div>
  </div></section>
</template>
<script setup>
import AppNumberInput from '~/components/ui/AppNumberInput.vue'
definePageMeta({layout:'admin',middleware:'staff'})
import {useAuthStore} from '~/stores/auth';import {useNotificationsStore} from '~/stores/notifications';import {createApiUrl} from '~/utils/api'
const auth=useAuthStore(),notifications=useNotificationsStore(),rules=ref([]),form=ref({min_subtotal:10000,percent:5,is_active:true});const api=(p,o={})=>auth.authFetch(createApiUrl(p),{credentials:'include',...o});const normalizeRule=r=>({...r,min_subtotal:Math.round(Number(r.min_subtotal||0)),percent:Math.round(Number(r.percent||0))});const load=async()=>{rules.value=(await api('/discount-rules/admin')).map(normalizeRule)};const createRule=async()=>{try{await api('/discount-rules/admin',{method:'POST',body:form.value});notifications.success('Уровень скидки добавлен');await load()}catch(e){notifications.error(e?.data?.message||'Не удалось добавить правило')}};const save=async r=>{try{await api(`/discount-rules/admin/${r.id}`,{method:'PATCH',body:{min_subtotal:r.min_subtotal,percent:r.percent,is_active:r.is_active}});notifications.success('Правило сохранено');await load()}catch(e){notifications.error(e?.data?.message||'Не удалось сохранить правило')}};const remove=async r=>{if(confirm('Удалить правило скидки?'))try{await api(`/discount-rules/admin/${r.id}`,{method:'DELETE'});notifications.info('Правило удалено');await load()}catch(e){notifications.error(e?.data?.message||'Не удалось удалить правило')}};const money=v=>`${new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(v||0))} ₽`;onMounted(load)
</script>
