scount-toggle>span{position:relative;width:38px;height:22px;border-radius:999px;background:#d7cec3;transition:.2s}.discount-toggle>span:after{content:'';position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:white;transition:.2s}.discount-toggle input:checked+span{background:#75603f}.discount-toggle input:checked+span:after{transform:translateX(16px)}.discount-toggle b{color:#6e6256;font-size:12px}.discount-rule__actions{display:flex;gap:8px}.discount-rule__actions .btn{min-height:40px;padding:8px 13px;font-size:12px}.discount-empty{padding:30px 0;margin:0;color:#817568;text-align:center}@media(max-width:820px){.discount-admin__layout{grid-template-columns:1fr}.discount-create{position:static}}@media(max-width:520px){.discount-rule__fields{grid-template-columns:1fr}.discount-create,.discount-rules{padding:18px}}
